CREATE TABLE cpf_notification_outbox (
 notification_no NUMBER(19) GENERATED BY DEFAULT AS IDENTITY, notification_id VARCHAR2(64) NOT NULL, channel_code VARCHAR2(32) NOT NULL, recipient_value VARCHAR2(1000) NOT NULL, template_id VARCHAR2(128) NOT NULL, variable_json CLOB NOT NULL, idempotency_key VARCHAR2(255) NOT NULL, transaction_id VARCHAR2(64) NOT NULL, notification_status VARCHAR2(32) NOT NULL, attempt_count INTEGER DEFAULT 0 NOT NULL, max_attempts INTEGER DEFAULT 5 NOT NULL, next_attempt_at TIMESTAMP, worker_id VARCHAR2(128), lease_until TIMESTAMP, provider_name VARCHAR2(128), provider_message_id VARCHAR2(255), result_detail VARCHAR2(2000), completed_at TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT pk_cpf_notification PRIMARY KEY(notification_no), CONSTRAINT uk_cpf_notification_id UNIQUE(notification_id), CONSTRAINT uk_cpf_notification_idem UNIQUE(idempotency_key));
CREATE INDEX ix_cpf_notification_claim ON cpf_notification_outbox(notification_status,next_attempt_at,lease_until);
